function integer(value, label) {
    if (!Number.isSafeInteger(value) || value < 0)
        throw new Error(`${label} must be a non-negative safe integer.`);
    return BigInt(value);
}
function roundedRatio(numerator, denominator, label) {
    if (denominator <= 0n)
        throw new Error(`${label} denominator must be positive.`);
    const value = (numerator * 2n + denominator) / (denominator * 2n);
    if (value < 0n || value > BigInt(Number.MAX_SAFE_INTEGER)) {
        throw new Error(`${label} exceeds safe sample arithmetic.`);
    }
    return Number(value);
}
/** Quantize one non-negative authored duration into the canonical sample domain exactly once. */
export function temporalDurationInSamples(duration, timeline, sampleRate = 48_000) {
    const rate = integer(sampleRate, "Sample rate");
    if (rate === 0n)
        throw new Error("Sample rate must be positive.");
    switch (duration.unit) {
        case "frames":
            return roundedRatio(integer(duration.value, "Frame duration") * rate * integer(timeline.frameRate.denominator, "Frame-rate denominator"), integer(timeline.frameRate.numerator, "Frame-rate numerator"), "Frame duration");
        case "milliseconds":
            return roundedRatio(integer(duration.value, "Millisecond duration") * rate, 1000n, "Millisecond duration");
        case "seconds":
            return roundedRatio(integer(duration.numerator, "Second duration numerator") * rate, integer(duration.denominator, "Second duration denominator"), "Second duration");
    }
}
